// packArgs ABI-encodes args under the comma-separated type list kinds.
func packArgs(t *testing.T, kinds string, args ...interface{}) []byte {
	t.Helper()
	var arguments abi.Arguments
	if kinds != "" {
		for _, kind := range strings.Split(kinds, ",") {
			typ, err := abi.NewType(kind, "", nil)
			require.NoError(t, err, kinds)
			arguments = append(arguments, abi.Argument{Type: typ})
		}
	}
	packed, err := arguments.Pack(args...)
	require.NoError(t, err, kinds)
	return packed
}

// calldata is the selector of signature followed by its encoded arguments.
func calldata(t *testing.T, signature string, args ...interface{}) []byte {
	t.Helper()
	open := strings.IndexByte(signature, '(')
	require.Positive(t, open, signature)
	return append(selector(signature), packArgs(t, signature[open+1:len(signature)-1], args...)...)
}

func retWord(t *testing.T, ret []byte, index int) []byte {
	t.Helper()
	require.GreaterOrEqual(t, len(ret), 32*(index+1))
	return ret[32*index : 32*(index+1)]
}

func retAddress(t *testing.T, ret []byte, index int) common.Address {
	return common.BytesToAddress(retWord(t, ret, index))
}

func retUint(t *testing.T, ret []byte, index int) *big.Int {
	return new(big.Int).SetBytes(retWord(t, ret, index))
}

func retBool(t *testing.T, ret []byte) bool {
	t.Helper()
	require.Len(t, ret, 32)
	value := retUint(t, ret, 0)
	require.True(t, value.Cmp(common.Big1) <= 0, "bool word %x", ret)
	return value.Sign() == 1
}

func revertData(sig string, words ...[]byte) []byte {
	out := selector(sig)
	for _, w := range words {
		out = append(out, w...)
	}
	return out
}

// retainedLayout is the generation table of
// modules/launchpad/keeper/testdata/v6120/layout.json.
type retainedLayout struct {
	Generations []struct {
		Generation         int            `json:"generation"`
		SidioraFactory     common.Address `json:"sidioraFactory"`
		PoolRegistry       common.Address `json:"poolRegistry"`
		PoolBeacon         common.Address `json:"poolBeacon"`
		PoolImplementation common.Address `json:"poolImplementation"`
	} `json:"generations"`
}

// retainedHarness runs the retained Launch-x contracts in the test EVM
// against the generation 2 role surfaces of the application's launchpad
// keeper. Every role surface of Generation2Surfaces holds the surface runtime
// and is registered with its role, as after the upgrade; markets are created
// and traded through the Router surface; USDL is a SidioraERC20 named by
// Params.QuoteToken, held by the creator and the trader with an allowance to
// 0x1017.
type retainedHarness struct {
	t        *testing.T
	stateDB  *state.DBImpl
	evm      *vm.EVM
	keeper   *launchpadkeeper.Keeper
	usdl     common.Address
	admin    common.Address
	creator  common.Address
	trader   common.Address
	timelock common.Address
}

func retainedAccount(name string) common.Address {
	return common.BytesToAddress(crypto.Keccak256([]byte(name))[12:])
}

func newRetainedHarness(t *testing.T) *retainedHarness {
	t.Helper()
	app := testkeeper.EVMTestApp
	ctx := app.GetContextForDeliverTx([]byte{}).WithBlockTime(retainedTime)
	ctx = ctx.WithGasMeter(sdk.NewInfiniteGasMeterWithMultiplier(ctx))
	ctx, _ = ctx.CacheContext()
	require.NotNil(t, app.LaunchpadKeeper)
	h := &retainedHarness{t: t, keeper: app.LaunchpadKeeper, admin: retainedAccount("retained admin"),
		creator: retainedAccount("retained creator"), trader: retainedAccount("retained trader"),
		timelock: retainedAccount("retained timelock")}
	h.stateDB = state.NewDBImpl(ctx, &app.EvmKeeper, false)
	blockCtx, err := app.EvmKeeper.GetVMBlockContext(ctx, core.GasPool(math.MaxUint64))
	require.NoError(t, err)
	cfg := evmtypes.DefaultChainConfig().EthereumConfig(app.EvmKeeper.ChainID(ctx))
	h.evm = vm.NewEVM(*blockCtx, h.stateDB, cfg, vm.Config{}, app.EvmKeeper.CustomPrecompiles(ctx))

	for role, address := range launchpadkeeper.Generation2Surfaces {
		h.stateDB.SetCode(address, surfaceRuntime)
		require.NoError(t, h.keeper.SetSurface(h.ctx(), address,
			launchpadkeeper.Surface{Role: role, Generation: types.Generation2}), role)
	}

	h.usdl = h.deploy(h.admin, retainedUSDLCreation, packArgs(t, "string,string,uint256,address", "USD Ledger", "USDL",
		big.NewInt(retainedUSDLSupply), h.admin))
	params := h.keeper.GetParams(h.ctx())
	params.QuoteToken = h.usdl.Hex()
	require.NoError(t, h.keeper.UpdateParams(h.ctx(), h.keeper.Authority(), params))
	for _, holder := range []common.Address{h.creator, h.trader} {
		h.send(h.admin, h.usdl, "transfer(address,uint256)", holder, big.NewInt(traderUSDL))
		h.send(holder, h.usdl, "approve(address,uint256)", launchpadAddress, maxUint256)
	}
	return h
}

func (h *retainedHarness) ctx() sdk.Context { return h.stateDB.Ctx() }

// deploy runs creation code with the encoded constructor arguments from
// from and returns the new contract.
func (h *retainedHarness) deploy(from common.Address, creation string, args []byte) common.Address {
	h.t.Helper()
	code := append(common.FromHex(creation), args...)
	_, address, _, err := h.evm.Create(from, code, retainedGas, uint256.NewInt(0))
	require.NoError(h.t, err)
	require.NotEmpty(h.t, h.stateDB.GetCode(address))
	return address
}

// deployProxy deploys implementation behind an ERC1967Proxy initialized by
// init.
func (h *retainedHarness) deployProxy(implementation string, init []byte) common.Address {
	h.t.Helper()
	impl := h.deploy(h.admin, implementation, nil)
	return h.deploy(h.admin, erc1967ProxyCreation, packArgs(h.t, "address,bytes", impl, init))
}

// installProxy places the ERC1967Proxy runtime at a retained address with
// implementation in the ERC1967 slot, the state the deployed proxy keeps at
// that address, and initializes it.
func (h *retainedHarness) installProxy(at common.Address, implementation string, init []byte) {
	h.t.Helper()
	impl := h.deploy(h.admin, implementation, nil)
	h.stateDB.SetCode(at, common.FromHex(erc1967ProxyRuntime))
	h.stateDB.SetState(at, erc1967ImplSlot, common.BytesToHash(impl.Bytes()))
	h.call(h.admin, at, init)
}

func (h *retainedHarness) try(from, to common.Address, gas uint64, input []byte) ([]byte, uint64, error) {
	h.t.Helper()
	ret, left, err := h.evm.Call(from, to, input, gas, uint256.NewInt(0))
	return ret, gas - left, err
}

func (h *retainedHarness) call(from, to common.Address, input []byte) []byte {
	h.t.Helper()
	ret, _, err := h.try(from, to, retainedGas, input)
	require.NoError(h.t, err, "call %s %x: revert %x", to.Hex(), input, ret)
	return ret
}

func (h *retainedHarness) send(from, to common.Address, signature string, args ...interface{}) []byte {
	h.t.Helper()
	return h.call(from, to, calldata(h.t, signature, args...))
}

// reverts requires the call to revert with exactly want.
func (h *retainedHarness) reverts(from, to common.Address, want []byte, signature string, args ...interface{}) {
	h.t.Helper()
	ret, _, err := h.try(from, to, retainedGas, calldata(h.t, signature, args...))
	require.ErrorIs(h.t, err, vm.ErrExecutionReverted, signature)
	require.Equal(h.t, want, ret, signature)
}

func (h *retainedHarness) view(to common.Address, signature string, args ...interface{}) []byte {
	h.t.Helper()
	ret, _, err := h.evm.StaticCall(h.trader, to, calldata(h.t, signature, args...), retainedGas)
	require.NoError(h.t, err, "view %s %s: revert %x", to.Hex(), signature, ret)
	return ret
}

func (h *retainedHarness) createMarket(creator common.Address, name, symbol string,
	optical common.Address) (common.Address, common.Address) {
	h.t.Helper()
	ret := h.send(creator, routerSurface, "createMarket(string,string,uint8,address)", name, symbol,
		uint8(types.FeeStrategyClaim), optical)
	token, pool := retAddress(h.t, ret, 0), retAddress(h.t, ret, 1)
	require.Equal(h.t, surfaceRuntime, h.stateDB.GetCode(pool))
	require.Equal(h.t, pool, retAddress(h.t, h.view(poolRegistrySurface, "getPoolByToken(address)", token), 0))
	return token, pool
}

func (h *retainedHarness) buy(trader, pool common.Address, amount int64) *big.Int {
	h.t.Helper()
	ret := h.send(trader, routerSurface, "buy(address,uint256,uint256,uint256)", pool, big.NewInt(amount),
		big.NewInt(0), retainedDeadline)
	out := retUint(h.t, ret, 0)
	require.Positive(h.t, out.Sign())
	return out
}

func (h *retainedHarness) balanceOf(token, holder common.Address) *big.Int {
	h.t.Helper()
	return retUint(h.t, h.view(token, "balanceOf(address)", holder), 0)
}

func (h *retainedHarness) logCount() int { return len(h.stateDB.GetAllLogs()) }

func (h *retainedHarness) logsSince(mark int) []*ethtypes.Log { return h.stateDB.GetAllLogs()[mark:] }

func readRetainedLayout(t *testing.T) retainedLayout {
	t.Helper()
	bz, err := os.ReadFile(filepath.Join("..", "..", "modules", "launchpad", "keeper", "testdata", "v6120", "layout.json"))
	require.NoError(t, err)
	var layout retainedLayout
	require.NoError(t, json.Unmarshal(bz, &layout))
	require.Len(t, layout.Generations, 2)
	require.Equal(t, 2, layout.Generations[1].Generation)
	return layout
}

// TestEventEmitterAuthorizationThroughSurfaces is acceptance 2.37.1: the
// retained generation 2 EventEmitter authorizes pools through
// isRegisteredPool at the PoolRegistry surface, and a buy emits the family
// Swap at 0x1017 and no MirrorFailed anywhere.
func TestEventEmitterAuthorizationThroughSurfaces(t *testing.T) {
	h := newRetainedHarness(t)
	emitter := h.keeper.Generation2().EventEmitter
	require.Equal(t, common.HexToAddress("0x622E1bb90E0E2B6E6e5e9e2DbE1555389E8A3EF6"), emitter)
	h.installProxy(emitter, eventEmitterCreation, calldata(t, "initialize(address)", h.admin))
	h.send(h.admin, emitter, "reinitializeV2(address)", h.admin)
	h.send(h.admin, emitter, "setPoolRegistry(address)", poolRegistrySurface)
	h.send(h.admin, emitter, "setSidioraFactory(address)", factorySurface)
	code := h.stateDB.GetCode(emitter)

	token, pool := h.createMarket(h.creator, "Kindle Token", "KNDL", common.Address{})
	require.Equal(t, emitter, retAddress(t, h.view(pool, "eventEmitter()"), 0))
	require.True(t, retBool(t, h.view(poolRegistrySurface, "isRegisteredPool(address)", pool)))
	require.False(t, retBool(t, h.view(poolRegistrySurface, "isRegisteredPool(address)", token)))

	require.True(t, retBool(t, h.view(emitter, "isAuthorizedEmitter(address)", pool)))
	require.True(t, retBool(t, h.view(emitter, "isAuthorizedEmitter(address)", poolRegistrySurface)))
	require.True(t, retBool(t, h.view(emitter, "isAuthorizedEmitter(address)", factorySurface)))
	require.False(t, retBool(t, h.view(emitter, "isAuthorizedEmitter(address)", token)))
	require.False(t, retBool(t, h.view(emitter, "isAuthorizedEmitter(address)", h.trader)))

	const emitSwap = "emitSwap(bytes32,address,bool,uint256,uint256,uint256,uint256)"
	poolID := common.BytesToHash(pool.Bytes())
	mark := h.logCount()
	h.send(pool, emitter, emitSwap, poolID, h.trader, true, big.NewInt(10), big.NewInt(9), big.NewInt(1), big.NewInt(7))
	mirrored := h.logsSince(mark)
	require.Len(t, mirrored, 1)
	require.Equal(t, emitter, mirrored[0].Address)
	require.Equal(t, []common.Hash{emitterSwapTopic, poolID, common.BytesToHash(h.trader.Bytes())}, mirrored[0].Topics)
	h.reverts(pool, emitter, unauthorizedError, emitSwap, common.BytesToHash(token.Bytes()), h.trader, true,
		big.NewInt(10), big.NewInt(9), big.NewInt(1), big.NewInt(7))
	h.reverts(h.trader, emitter, unauthorizedError, emitSwap, common.BytesToHash(h.trader.Bytes()), h.trader, true,
		big.NewInt(10), big.NewInt(9), big.NewInt(1), big.NewInt(7))

	mark = h.logCount()
	h.buy(h.trader, pool, 1_000_000)
	swaps := 0
	for _, log := range h.logsSince(mark) {
		require.NotEqual(t, mirrorFailedTopic, log.Topics[0], "MirrorFailed at %s", log.Address.Hex())
		require.NotEqual(t, emitter, log.Address)
		if log.Topics[0] == emitterSwapTopic {
			require.Equal(t, launchpadAddress, log.Address)
			require.Equal(t, poolID, log.Topics[1])
			swaps++
		}
	}
	require.Equal(t, 1, swaps)
	require.Equal(t, code, h.stateDB.GetCode(emitter))
}

// TestOpticalFactoryAfterUpgrade is acceptance 2.37.2: createLaunchpadOptical
// authorizes the optical at the FeeAccumulator surface through the migrated
// OPTICAL_GRANTER_ROLE, a market created with it registers it, and a buy runs
// beforeSwap at the optical without NotPool.
func TestOpticalFactoryAfterUpgrade(t *testing.T) {
	h := newRetainedHarness(t)
	h.installProxy(generation2OpticalRegistry, opticalRegistryCreation,
		calldata(t, "initialize(address,address)", h.keeper.Generation2().EventEmitter, h.admin))
	factory := h.deployProxy(launchpadOpticalFactoryCreation, calldata(t, "initialize(address,address,address,address)",
		poolRegistrySurface, feeAccumulatorSurface, generation2OpticalRegistry, h.admin))
	require.Equal(t, opticalGranterRole, common.BytesToHash(h.view(feeAccumulatorSurface, "OPTICAL_GRANTER_ROLE()")))
	require.Equal(t, opticalClaimRole, common.BytesToHash(h.view(feeAccumulatorSurface, "OPTICAL_CLAIM_ROLE()")))

	const create = "createLaunchpadOptical(address[],uint256,uint256,uint256,uint256,address)"
	cliff, vesting, raiseBps, raise := big.NewInt(30*86400), big.NewInt(90*86400), big.NewInt(500), big.NewInt(30*86400)
	h.reverts(h.creator, factory, revertData("MissingRole(address,bytes32)", addressWord(factory), opticalGranterRole.Bytes()),
		create, []common.Address{}, cliff, vesting, raiseBps, raise, h.creator)

	granted, err := h.keeper.GovernanceGrant(h.ctx(), h.keeper.Authority(), feeAccumulatorSurface, opticalGranterRole, factory)
	require.NoError(t, err)
	require.True(t, granted)
	optical := retAddress(t, h.send(h.creator, factory, create, []common.Address{}, cliff, vesting, raiseBps, raise, h.creator), 0)
	require.NotEmpty(t, h.stateDB.GetCode(optical))
	require.True(t, retBool(t, h.view(feeAccumulatorSurface, "hasRole(bytes32,address)", opticalClaimRole, optical)))
	require.Equal(t, big.NewInt(1), retUint(t, h.view(factory, "getDeployedCount()"), 0))

	// The creation transfer of the virtual token supply to the pool runs the
	// optical's beforeTokenTransfer, which records the start once
	// (Launch-x:contracts/contracts/core/SidioraFactory.sol:150-154,
	// Launch-x:contracts/contracts/opticals/presets/LaunchpadOptical.sol:179-202);
	// later swaps find it recorded.
	mark := h.logCount()
	token, pool := h.createMarket(h.creator, "Optical Token", "OPTX", optical)
	started := func(mark int) int {
		count := 0
		for _, log := range h.logsSince(mark) {
			if log.Address == optical && log.Topics[0] == poolStartTimeTopic {
				require.Equal(t, common.BytesToHash(pool.Bytes()), log.Topics[1])
				require.Equal(t, big.NewInt(retainedTime.Unix()), new(big.Int).SetBytes(log.Data))
				count++
			}
		}
		return count
	}
	require.Equal(t, 1, started(mark))
	metadata := h.view(poolRegistrySurface, "getPoolMetadata(address)", pool)
	require.Equal(t, h.creator, retAddress(t, metadata, 0))
	require.Equal(t, token, retAddress(t, metadata, 1))
	require.Equal(t, optical, retAddress(t, metadata, 2))
	require.Equal(t, optical, retAddress(t, h.view(pool, "opticalAddress()"), 0))

	mark = h.logCount()
	bought := h.buy(h.trader, pool, 1_000_000)
	require.Equal(t, bought, h.balanceOf(token, h.trader))
	require.Zero(t, started(mark))
	h.buy(h.trader, pool, 1_000_000)
}

// TestPoolBeaconRetained is acceptance 2.37.3: the generation 2 PoolBeacon
// keeps its code and halt-height implementation, answers as the contract
// does, and is the beacon of the predicted pool address.
func TestPoolBeaconRetained(t *testing.T) {
	h := newRetainedHarness(t)
	layout := readRetainedLayout(t)
	generation2 := layout.Generations[1]
	beacon := h.keeper.Generation2().PoolBeacon
	require.Equal(t, generation2.PoolBeacon, beacon)
	require.Equal(t, generation2.SidioraFactory, factorySurface)
	require.Equal(t, generation2.PoolRegistry, poolRegistrySurface)

	deployed := h.deploy(h.admin, poolBeaconCreation, packArgs(t, "address,address", h.usdl, h.timelock))
	require.Equal(t, common.FromHex(poolBeaconRuntime), h.stateDB.GetCode(deployed))
	require.Equal(t, h.usdl, retAddress(t, h.view(deployed, "implementation()"), 0))
	h.stateDB.SetCode(beacon, common.FromHex(poolBeaconRuntime))
	h.stateDB.SetState(beacon, common.Hash{}, common.BytesToHash(generation2.PoolImplementation.Bytes()))
	h.stateDB.SetState(beacon, common.BigToHash(common.Big1), common.BytesToHash(h.timelock.Bytes()))

	require.Equal(t, beacon, retAddress(t, h.view(factorySurface, "poolBeacon()"), 0))
	token, pool := h.createMarket(h.creator, "Beacon Token", "BCN", common.Address{})
	require.Equal(t, pool, retAddress(t, h.view(factorySurface, "predictPoolAddress(address,address,address)", token,
		h.creator, common.Address{}), 0))
	predicted, err := h.keeper.PredictPoolAddress(h.ctx(), token, h.creator, common.Address{})
	require.NoError(t, err)
	require.Equal(t, pool, predicted)

	require.Equal(t, common.FromHex(poolBeaconRuntime), h.stateDB.GetCode(beacon))
	require.Equal(t, generation2.PoolImplementation, retAddress(t, h.view(beacon, "implementation()"), 0))
	require.Equal(t, h.timelock, retAddress(t, h.view(beacon, "owner()"), 0))
	require.Equal(t, common.Address{}, retAddress(t, h.view(beacon, "pendingOwner()"), 0))
	h.reverts(h.trader, beacon, unauthorizedError, "upgradeTo(address)", h.usdl)
	h.reverts(h.trader, beacon, unauthorizedError, "transferOwnership(address)", h.trader)
	h.reverts(h.trader, beacon, unauthorizedError, "acceptOwnership()")
	h.reverts(h.timelock, beacon, invalidImplementation, "upgradeTo(address)", h.trader)
	require.Equal(t, generation2.PoolImplementation, retAddress(t, h.view(beacon, "implementation()"), 0))
}

// TestPauseControllerAgainstSurfaces is acceptance 2.37.4: pauseTargets
// pauses a pool surface whose guardian is the controller within the 150000
// and 30000 gas budgets, any other pool refuses with Unauthorized() as at
// the halt height, and a DEFAULT_ADMIN_ROLE method executed by the Timelock
// at a surface reverts AccessControlUnauthorizedAccount.
func TestPauseControllerAgainstSurfaces(t *testing.T) {
	h := newRetainedHarness(t)
	responder := retainedAccount("retained responder")
	_, guarded := h.createMarket(h.creator, "Guarded Token", "GRD", common.Address{})
	_, other := h.createMarket(h.creator, "Other Token", "OTH", common.Address{})
	controller := h.deploy(h.admin, emergencyPauseControllerCreation, packArgs(t, "address,address,address[]",
		h.timelock, responder, []common.Address{guarded, other}))

	require.Equal(t, h.creator, retAddress(t, h.view(guarded, "guardian()"), 0))
	h.reverts(h.trader, guarded, unauthorizedError, "transferGuardian(address)", controller)
	h.send(h.creator, guarded, "transferGuardian(address)", controller)
	require.Equal(t, controller, retAddress(t, h.view(guarded, "pendingGuardian()"), 0))
	h.reverts(h.trader, guarded, unauthorizedError, "acceptGuardian()")
	h.send(controller, guarded, "acceptGuardian()")
	require.Equal(t, controller, retAddress(t, h.view(guarded, "guardian()"), 0))
	h.reverts(controller, other, unauthorizedError, "pause()")

	status, statusGasUsed, err := h.try(controller, guarded, statusGas, calldata(t, "emergencyPaused()"))
	require.NoError(t, err)
	require.False(t, retBool(t, status))
	require.Less(t, statusGasUsed, statusGas)
	require.False(t, retBool(t, h.view(guarded, "paused()")))
	require.False(t, retBool(t, h.view(other, "paused()")))

	incident := crypto.Keccak256Hash([]byte("retained incident"))
	targets := []common.Address{guarded, other}
	h.reverts(h.trader, controller, revertData("MissingRole(address,bytes32)", addressWord(h.trader),
		crypto.Keccak256([]byte("INCIDENT_GUARDIAN_ROLE"))), "pauseTargets(address[],bytes32)", targets, incident)
	mark := h.logCount()
	h.send(responder, controller, "pauseTargets(address[],bytes32)", targets, incident)
	results := map[common.Address]uint64{}
	for _, log := range h.logsSince(mark) {
		if log.Address == controller && log.Topics[0] == incidentTargetResultTopic {
			require.Equal(t, incident, log.Topics[1])
			results[common.BytesToAddress(log.Topics[2].Bytes())] = new(big.Int).SetBytes(log.Data).Uint64()
		}
	}
	require.Equal(t, map[common.Address]uint64{guarded: pauseStatusPaused, other: pauseStatusCallFailed}, results)
	require.True(t, retBool(t, h.view(guarded, "paused()")))
	require.True(t, retBool(t, h.view(guarded, "emergencyPaused()")))
	require.False(t, retBool(t, h.view(other, "paused()")))

	_, fresh := h.createMarket(h.creator, "Fresh Token", "FRS", common.Address{})
	h.send(h.creator, fresh, "transferGuardian(address)", controller)
	h.send(controller, fresh, "acceptGuardian()")
	_, pauseGasUsed, err := h.try(controller, fresh, pauseGasBudget, calldata(t, "pause()"))
	require.NoError(t, err)
	require.Less(t, pauseGasUsed, pauseGasBudget)
	require.True(t, retBool(t, h.view(fresh, "paused()")))

	adminRefusal := revertData("AccessControlUnauthorizedAccount(address,bytes32)", addressWord(h.timelock),
		make([]byte, 32))
	require.Equal(t, []byte{0xe2, 0x51, 0x7d, 0x3f}, adminRefusal[:4])
	h.reverts(h.timelock, feeAccumulatorSurface, adminRefusal, "grantRole(bytes32,address)", opticalGranterRole, h.timelock)
	h.reverts(h.timelock, factorySurface, adminRefusal, "upgradeToAndCall(address,bytes)", h.usdl, []byte{})
	h.reverts(h.timelock, poolRegistrySurface, adminRefusal, "revokeRole(bytes32,address)", opticalGranterRole, h.creator)
}

// TestSidioraAdapterAfterRepoint is acceptance 2.37.5: the meta-ag
// SidioraAdapter holding the generation 2 Router, Quoter and PoolRegistry
// surfaces swaps USDL for a pool token once its admin points sidioraRouter at
// 0x1017, where the pulls run with spender 0x1017.
func TestSidioraAdapterAfterRepoint(t *testing.T) {
	h := newRetainedHarness(t)
	adapter := h.deploy(h.admin, sidioraAdapterCreation, packArgs(t, "address,address,address,address,address",
		poolRegistrySurface, quoterSurface, routerSurface, h.usdl, h.admin))
	require.Equal(t, poolRegistrySurface, retAddress(t, h.view(adapter, "poolRegistry()"), 0))
	require.Equal(t, quoterSurface, retAddress(t, h.view(adapter, "quoter()"), 0))
	require.Equal(t, routerSurface, retAddress(t, h.view(adapter, "sidioraRouter()"), 0))

	token, pool := h.createMarket(h.creator, "Adapter Token", "ADPT", common.Address{})
	require.Equal(t, pool, retAddress(t, h.view(poolRegistrySurface, "getPoolByToken(address)", token), 0))
	require.True(t, retBool(t, h.view(adapter, "supportsSwap(address,address)", h.usdl, token)))
	require.True(t, retBool(t, h.view(adapter, "supportsSwap(address,address)", token, h.usdl)))
	require.False(t, retBool(t, h.view(adapter, "supportsSwap(address,address)", h.usdl, h.trader)))

	const executeSwap = "executeSwap(address,address,uint256,uint256,address,address,uint256,bytes)"
	amountIn := big.NewInt(1_000_000)
	route := packArgs(t, "uint8,address,address", uint8(0), pool, common.Address{})
	h.send(h.trader, h.usdl, "approve(address,uint256)", adapter, amountIn)
	_, _, err := h.try(h.trader, adapter, retainedGas, calldata(t, executeSwap, h.usdl, token, amountIn, big.NewInt(0),
		h.trader, h.trader, big.NewInt(0), route))
	require.ErrorIs(t, err, vm.ErrExecutionReverted)
	same(t, big.NewInt(0), h.balanceOf(token, h.trader))

	h.reverts(h.trader, adapter, revertData("MissingRole(address,bytes32)", addressWord(h.trader), make([]byte, 32)),
		"setSidioraRouter(address)", launchpadAddress)
	h.send(h.admin, adapter, "setSidioraRouter(address)", launchpadAddress)
	require.Equal(t, launchpadAddress, retAddress(t, h.view(adapter, "sidioraRouter()"), 0))

	usdlBefore := h.balanceOf(h.usdl, h.trader)
	ret := h.send(h.trader, adapter, executeSwap, h.usdl, token, amountIn, big.NewInt(1), h.trader, h.trader,
		big.NewInt(0), route)
	require.Equal(t, big.NewInt(32), retUint(t, ret, 0))
	amountOut := retUint(t, ret, 1)
	require.Positive(t, amountOut.Sign())
	require.Equal(t, amountOut, h.balanceOf(token, h.trader))
	require.Equal(t, new(big.Int).Sub(usdlBefore, amountIn), h.balanceOf(h.usdl, h.trader))
	same(t, big.NewInt(0), h.balanceOf(h.usdl, adapter))
	same(t, big.NewInt(0), h.balanceOf(token, adapter))
	same(t, big.NewInt(0), retUint(t, h.view(h.usdl, "allowance(address,address)", adapter, launchpadAddress), 0))
	require.Equal(t, pool, retAddress(t, h.view(poolRegistrySurface, "getPoolByToken(address)", token), 0))
}
